--1. Reads the currently applied value (the value column shows the actually applied value)
SHOW PARAMETERS LIKE 'CORTEX_ENABLED_CROSS_REGION' IN ACCOUNT;

--2. Limits processing to within the same cloud environment only.
ALTER ACCOUNT SET CORTEX_ENABLED_CROSS_REGION = 'AWS_GLOBAL';

--3. Limits both cloud and region (multiple values can be combined with commas)
ALTER ACCOUNT SET CORTEX_ENABLED_CROSS_REGION = 'AWS_EU,AZURE_EU';

--4. Process only within the home region of the account (most strict)
ALTER ACCOUNT SET CORTEX_ENABLED_CROSS_REGION = 'DISABLED';

--5. Broadest scope: handles requests from any region
ALTER ACCOUNT SET CORTEX_ENABLED_CROSS_REGION = 'ANY_REGION';
